/*!40000 ALTER TABLE `llm_indicator` ENABLE KEYS */;

--
-- Table structure for table `llm_indicator_value_option`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_indicator_value_option` (
  `id` bigint NOT NULL COMMENT '指标值域项ID',
  `indicator_id` bigint NOT NULL COMMENT '所属指标ID',
  `value_label` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '运行时使用的规范值标签',
  `default_value` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧版默认值兼容字段',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否为默认值：1是、0否',
  `value_kind` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DOMAIN_VALUE' COMMENT '值类别',
  `inference_basis` text COLLATE utf8mb4_unicode_ci COMMENT '该值的推理依据',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_llm_value_option_indicator_sort` (`indicator_id`,`sort_order`,`id`),
  CONSTRAINT `chk_llm_value_option_default` CHECK ((`is_default` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI指标结构化值域表';
/*!40101 SET character_set_client = @saved_cs_client */;

