INSERT INTO `llm_indicator_value_option` VALUES (10989,5784,'浅表烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“浅表烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',0,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10990,5784,'浅Ⅱ度烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“浅Ⅱ度烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',1,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10991,5784,'浅层深Ⅱ度烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“浅层深Ⅱ度烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',2,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10992,5784,'深层深Ⅱ度烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“深层深Ⅱ度烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',3,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10993,5784,'Ⅲ度全层烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“Ⅲ度全层烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',4,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10994,5784,'Ⅳ度烧伤',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“Ⅳ度烧伤”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',5,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10995,5784,'混合',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_depth_visual_estimate 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“混合”，且符合以下可见性要求：综合色泽、湿润度、水疱、焦痂、炭化及深部组织暴露；图像不能替代痛觉和毛细血管再充盈时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',6,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(10996,5784,'无法确定','1',1,'DOMAIN_VALUE','本指标配置默认值为“无法确定”；有明确证据时按当前选项提取实际值，缺失或无效输入的提取状态单独记录。',7,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11044,5789,'存在',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_eschar_visual_presence 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“存在”，且符合以下可见性要求：识别干硬、无弹性、棕黑或皮革样覆盖，避免把干燥敷料误作焦痂时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',0,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11045,5789,'不存在','1',1,'DOMAIN_VALUE','本指标配置默认值为“不存在”；有明确证据时按当前选项提取实际值，缺失或无效输入的提取状态单独记录。',1,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11052,5791,'不存在','1',1,'DOMAIN_VALUE','本指标配置默认值为“不存在”；有明确证据时按当前选项提取实际值，缺失或无效输入的提取状态单独记录。',0,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11054,5791,'存在',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_infection_visual_presence 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“存在”，且符合以下可见性要求：依据脓性/血性分泌物、创周炎症扩大、坏死或创面加深；照片只能提示，不能确诊感染时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',2,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11061,5793,'开放创面',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_healing_stage_image 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“开放创面”，且符合以下可见性要求：根据创面覆盖和上皮化外观判定；敷料遮挡时不得估计时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',0,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11062,5793,'部分上皮化',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_healing_stage_image 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“部分上皮化”，且符合以下可见性要求：根据创面覆盖和上皮化外观判定；敷料遮挡时不得估计时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',1,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11063,5793,'完全上皮化',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_healing_stage_image 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“完全上皮化”，且符合以下可见性要求：根据创面覆盖和上皮化外观判定；敷料遮挡时不得估计时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',2,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11064,5793,'再次破溃',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_healing_stage_image 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“再次破溃”，且符合以下可见性要求：根据创面覆盖和上皮化外观判定；敷料遮挡时不得估计时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',3,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11065,5793,'已植皮',NULL,0,'DOMAIN_VALUE','核对图像识别 JSON 中同名字段 burn_healing_stage_image 以及同一病灶、同一时间点的相关图像证据。仅当字段明确返回中文规范值“已植皮”，且符合以下可见性要求：根据创面覆盖和上皮化外观判定；敷料遮挡时不得估计时返回该值；照片未覆盖、遮挡或质量不足时不得猜测。',4,'2026-07-29 17:22:57','2026-07-29 17:22:57'),(11066,5793,'未知','1',1,'UNKNOWN_STATUS','本指标配置默认值为“未知”；有明确证据时按当前选项提取实际值，缺失或无效输入的提取状态单独记录。'