--
-- Table structure for table `llm_indicator_group`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_indicator_group` (
  `id` bigint NOT NULL COMMENT '指标组ID',
  `disease_id` bigint NOT NULL COMMENT '所属病种ID',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标组名称',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标组说明',
  `trigger_condition` text COLLATE utf8mb4_unicode_ci COMMENT '旧版文本触发条件，迁移期保留',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_llm_group_disease_sort` (`disease_id`,`sort_order`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI病种触发指标组表';
/*!40101 SET character_set_client = @saved_cs_client */;

