INSERT INTO `llm_indicator_group` VALUES (692,2,'B02 烧伤病因分型树病种触发组','对应 B02 烧伤病因分型树，按医学指标初稿的病种触发条件分组。','烧伤致伤机制 已取得有效值；或 化学品接触状态 等于 存在；或 电流暴露状态 等于 存在；或 烟雾暴露状态 等于 存在',3,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(694,2,'B10 烧伤深度分级树病种触发组','对应 B10 烧伤深度分级树，按医学指标初稿的病种触发条件分组。','烧伤视觉初判深度 已取得有效值；或 焦痂视觉存在状态 等于 存在',5,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(695,2,'烧伤面积病种触发组','创面局部面积换算烧伤总面积所需的输入条件。','医生记录烧伤部位 已取得有效值 且 创面局部面积 已取得有效值',6,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(696,2,'B12 化学烧伤风险树病种触发组','对应 B12 化学烧伤风险树，按医学指标初稿的病种触发条件分组。','化学品接触状态 等于 存在；或 烧伤致伤机制 等于 化学烧伤；或 烧伤致伤机制 等于 混合',7,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(697,2,'B13 电损伤风险树病种触发组','对应 B13 电损伤风险树，按医学指标初稿的病种触发条件分组。','电流暴露状态 等于 存在；或 烧伤致伤机制 等于 电烧伤；或 烧伤致伤机制 等于 雷击伤；或 烧伤致伤机制 等于 混合',8,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(698,2,'B14 吸入伤与燃烧产物中毒树病种触发组','对应 B14 吸入伤与燃烧产物中毒树，按医学指标初稿的病种触发条件分组。','烟雾暴露状态 等于 存在；或 密闭空间暴露状态 等于 存在；或 呼吸道症状总状态 等于 存在',9,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(700,2,'B20 烧伤严重度与预后评分树病种触发组','对应 B20 烧伤严重度与预后评分树，按医学指标初稿的病种触发条件分组。','患者年龄 已取得有效值；或 患者年龄 已取得有效值 且 烧伤视觉初判深度 已取得有效值；或 患者年龄 已取得有效值 且 医生记录烧伤部位 已取得有效值',11,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(702,2,'B22 环形焦痂与间隔综合征树病种触发组','对应 B22 环形焦痂与间隔综合征树，按医学指标初稿的病种触发条件分组。','电流暴露状态 等于 存在 且 间隔综合征临床征象 至少有一项；或 间隔综合征临床征象 至少有一项；或 间隔综合征临床征象 至少有一项 且 烧伤视觉初判深度 等于 浅层深Ⅱ度烧伤；或 间隔综合征临床征象 至少有一项 且 烧伤视觉初判深度 等于 深层深Ⅱ度烧伤；或 间隔综合征临床征象 至少有一项 且 烧伤视觉初判深度 等于 Ⅲ度全层烧伤；或 间隔综合征临床征象 至少有一项 且 烧伤视觉初判深度 等于 Ⅳ度烧伤；或 间隔综合征临床征象 至少有一项 且 烧伤视觉初判深度 等于 混合',13,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(703,2,'B23 Ⅱ度烧伤水疱处理树病种触发组','对应 B23 Ⅱ度烧伤水疱处理树，按医学指标初稿的病种触发条件分组。','烧伤视觉初判深度 等于 浅Ⅱ度烧伤；或 烧伤视觉初判深度 等于 浅层深Ⅱ度烧伤；或 烧伤视觉初判深度 等于 深层深Ⅱ度烧伤；或 烧伤视觉初判深度 等于 混合',14,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(704,2,'B24 烧伤创面感染树病种触发组','对应 B24 烧伤创面感染树，按医学指标初稿的病种触发条件分组。','烧伤创面感染视觉提示 等于 存在；或 糖尿病状态 不等于 无；或 糖尿病状态 不等于 无 且 局部感染临床征象 至少有一项；或 糖尿病状态 不等于 无 且 医生烧伤脓毒症初步判断 不等于 无脓毒症；或 免疫抑制状态 不等于 无；或 免疫抑制状态 不等于 无 且 局部感染临床征象 至少有一项；或 免疫抑制状态 不等于 无 且 医生烧伤脓毒症初步判断 不等于 无脓毒症',15,'2026-07-29 17:22:58','2026-08-24 17:51:34'),(709,2,'B32 创面闭合与手术指征树病种触发组','对应 B32 创面闭合与手术指征树，按医学指标初稿的病种触发条件分组。','烧伤创面愈合阶段 已取得有效值；或 创面完全愈合用时 已取得有效值；或 创面上皮化比例 已取得有效值；或 创基活力 已取得有效值',20,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(712,2,'B41 烧伤康复与瘢痕风险树病种触发组','对应 B41 烧伤康复与瘢痕风险树，按医学指标初稿的病种触发条件分组。','烧伤创面愈合阶段 已取得有效值；或 烧伤随访图像可比性 已取得有效值；或 医生记录烧伤部位 包含 主要关节；或 伤后时间 大于 504 且 烧伤创面愈合阶段 等于 开放创面；或 伤后时间 大于 504 且 烧伤创面愈合阶段 等于 部分上皮化；或 烧伤当前功能状态 不等于 完整',23,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(713,3,'瘢痕来源树病种触发组','已有瘢痕来源记录时进入。','瘢痕来源 已取得有效值',1,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(716,3,'S11 瘢痕边界与形态树病种触发组','对应 S11 瘢痕边界与形态树，按医学指标初稿的病种触发条件分组。','瘢痕隆起视觉状态 已取得有效值；或 瘢痕凹陷视觉状态 已取得有效值；或 瘢痕挛缩视觉状态 已取得有效值',4,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(717,3,'S12 瘢痕成熟与活动度树病种触发组','对应 S12 瘢痕成熟与活动度树，按医学指标初稿的病种触发条件分组。','伤后时长 已取得有效值；或 创面愈合后时长 已取得有效值；或 瘢痕生长过程 已取得有效值；或 瘢痕红度视觉状态 已取得有效值',5,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(718,3,'S13 病理性瘢痕风险树病种触发组','对应 S13 病理性瘢痕风险树，按医学指标初稿的病种触发条件分组。','瘢痕来源 已取得有效值 且 既往病理性瘢痕史 已取得有效值；或 瘢痕来源 已取得有效值 且 病理性瘢痕家族史 已取得有效值；或 瘢痕来源 已取得有效值 且 Fitzpatrick 皮肤分型 已取得有效值；或 瘢痕来源 已取得有效值 且 高张力部位状态 已取得有效值；或 瘢痕来源 已取得有效值 且 反复运动牵拉状态 已取得有效值；或 瘢痕来源 已取得有效值 且 瘢痕系统性风险因素 已取得有效值；或 瘢痕来源 已取得有效值 且 患者年龄 已取得有效值；或 瘢痕来源 已取得有效值 且 生长发育/激素阶段 已取得有效值',6,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(719,3,'瘢痕客观测量评分触发组','任一可量化瘢痕测量项已取得有效值时进入。','瘢痕平面面积 已取得有效值；或 瘢痕最长径 已取得有效值；或 瘢痕最大垂直径 已取得有效值；或 瘢痕隆起高度 已取得有效值；或 瘢痕组织厚度 已取得有效值；或 瘢痕校准亮度 L* 已取得有效值；或 瘢痕校准红绿轴 a* 已取得有效值；或 瘢痕校准黄蓝轴 b* 已取得有效值；或 瘢痕客观血管指数 已取得有效值；或 瘢痕随访面积变化率 已取得有效值；或 瘢痕随访高度变化率 已取得有效值',7,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(720,3,'S21 温哥华瘢痕量表 评分树病种触发组','对应 S21 温哥华瘢痕量表 评分树，按医学指标初稿的病种触发条件分组。','瘢痕主色类别 已取得有效值；或 瘢痕血管性红度 已取得有效值；或 瘢痕色素状态 已取得有效值；或 瘢痕触诊柔软度 已取得有效值',8,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(723,3,'S20 增生性瘢痕与瘢痕疙瘩判别树病种触发组','对应 S20 增生性瘢痕与瘢痕疙瘩判别树，按医学指标初稿的病种触发条件分组。','瘢痕隆起视觉状态 等于 存在',11,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(724,3,'S24 瘢痕挛缩与功能树病种触发组','对应 S24 瘢痕挛缩与功能树，按医学指标初稿的病种触发条件分组。','瘢痕挛缩视觉状态 等于 存在 且 瘢痕功能影响状态 等于 存在',12,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(725,3,'S25 瘢痕症状负担树病种触发组','对应 S25 瘢痕症状负担树，按医学指标初稿的病种触发条件分组。','瘢痕疼痛存在状态 已取得有效值；或 瘢痕瘙痒存在状态 已取得有效值；或 瘢痕疼痛评分 已取得有效值；或 瘢痕瘙痒评分 已取得有效值',13,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(727,3,'S30 瘢痕综合严重度树病种触发组','对应 S30 瘢痕综合严重度树，按医学指标初稿的病种触发条件分组。','瘢痕形态分类 已取得有效值 且 瘢痕成熟阶段 已取得有效值 且 病理性瘢痕风险等级 已取得有效值；或 瘢痕形态分类 已取得有效值 且 瘢痕成熟阶段 已取得有效值 且 病理性瘢痕风险等级 已取得有效值 且 瘢痕症状负担等级 已取得有效值；或 瘢痕形态分类 已取得有效值 且 瘢痕成熟阶段 已取得有效值 且 病理性瘢痕风险等级 已取得有效值 且 瘢痕挛缩功能等级 已取得有效值',15,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(729,3,'S32 瘢痕疗效与复发树病种触发组','对应 S32 瘢痕疗效与复发树，按医学指标初稿的病种触发条件分组。','既往/当前瘢痕治疗类别 至少有一项；或 瘢痕复发视觉提示 已取得有效值；或 瘢痕随访图像可比性 已取得有效值；或 既往治疗总体反应 已取得有效值',17,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(730,3,'S40 瘢痕管理路径与专科转诊树病种触发组','对应 S40 瘢痕管理路径与专科转诊树，按医学指标初稿的病种触发条件分组。','瘢痕形态分类 已取得有效值 且 瘢痕综合严重度 已取得有效值',18,'2026-07-29 17:22:58','2026-08-24 17:51:35'),(732,3,'S42 瘢痕随访优先级树病种触发组','对应 S42 瘢痕随访优先级树，按医学指标初稿的病种触发条件分组。','瘢痕管理路径 已取得有效值；或 瘢痕专科转诊需求 已取得有效值；或 瘢痕综合严重度 已取得有效值；或 瘢痕治疗反应状态 已取得有效值',20,'2026-07-29 17:22:58','2026-08-24 17:51:35');
/*!40000 ALTER TABLE `llm_indicator_group` ENABLE KEYS */;

--
-- Table structure for table `llm_indicator_group_item`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_indicator_group_item` (
  `id` bigint NOT NULL COMMENT '指标组条件项ID',
  `group_id` bigint NOT NULL COMMENT '所属指标组ID',
  `indicator_id` bigint DEFAULT NULL COMMENT '关联指标ID；纯文本条件时可为空',
  `required` tinyint NOT NULL DEFAULT '1' COMMENT '是否必须满足：1是、0否',
  `card_group` int NOT NULL DEFAULT '0' COMMENT '条件卡片编号；卡内AND、卡间OR',
  `comparison_operator` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '比较运算符',
  `expected_value` text COLLATE utf8mb4_unicode_ci COMMENT '期望值',
  `condition_expression` text COLLATE utf8mb4_unicode_ci COMMENT '旧版完整条件表达式',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '卡片内排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_llm_group_item_group_card_sort` (`group_id`,`card_group`,`sort_order`,`id`),
  KEY `idx_llm_group_item_indicator` (`indicator_id`),
  CONSTRAINT `chk_llm_group_item_required` CHECK ((`required` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI指标组结构化条件项表';
/*!40101 SET character_set_client = @saved_cs_client */;

