--
-- Table structure for table `llm_decision_tree`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_decision_tree` (
  `id` bigint NOT NULL COMMENT '决策树ID',
  `disease_id` bigint NOT NULL COMMENT '所属病种ID',
  `indicator_group_id` bigint DEFAULT NULL COMMENT '触发该树的指标组ID',
  `code` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定决策树编码',
  `name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '决策树名称',
  `level_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧版层级名称，迁移期保留',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '医学用途说明',
  `unlock_condition` text COLLATE utf8mb4_unicode_ci COMMENT '旧版解锁条件，迁移期保留',
  `prerequisite_condition` text COLLATE utf8mb4_unicode_ci COMMENT '旧版前置条件，迁移期保留',
  `graph_position_x` int DEFAULT NULL COMMENT '总览图横坐标',
  `graph_position_y` int DEFAULT NULL COMMENT '总览图纵坐标',
  `tree_json` text COLLATE utf8mb4_unicode_ci COMMENT '旧版整树JSON，迁移期保留',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT '配置状态',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '执行和展示排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_llm_decision_tree_code` (`code`),
  KEY `idx_llm_tree_disease_sort` (`disease_id`,`sort_order`,`id`),
  KEY `idx_llm_tree_group` (`indicator_group_id`),
  KEY `idx_llm_tree_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI决策树配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `llm_decision_tree`
--

