INSERT INTO `llm_decision_tree` VALUES (692,2,692,'B02','烧伤病因分型树','直接运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER, CN-二型-2024-I','直接运行。','直接运行。',72,92,NULL,'ENABLED',3,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(694,2,694,'B10','烧伤深度分级树','直接运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER, CN-二型-2024-I','直接运行。','直接运行。',72,256,NULL,'ENABLED',5,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(695,2,695,'B11','烧伤面积与特殊部位树','直接运行','根据创面局部面积、医生记录烧伤部位、患者年龄和体型估算烧伤总面积（%TBSA），再按总面积进行分层；计算依据见烧伤总面积指标说明。','直接运行。','直接运行。',72,420,NULL,'ENABLED',6,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(696,2,696,'B12','化学烧伤风险树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER, CN-二型-2024-I, ISBI','完成「B02 烧伤病因分型树」，且满足：烧伤病因分类 等于 化学烧伤；或 烧伤病因分类 等于 混合后运行。','完成「B02 烧伤病因分型树」，且满足：烧伤病因分类 等于 化学烧伤；或 烧伤病因分类 等于 混合后运行。',430,92,NULL,'ENABLED',7,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(697,2,697,'B13','电损伤风险树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：ABA-REF, ISBI, BURN-PRIMER','完成「B02 烧伤病因分型树」，且满足：烧伤病因分类 等于 电损伤未分型；或 烧伤病因分类 等于 雷击伤；或 烧伤病因分类 等于 混合后运行。','完成「B02 烧伤病因分型树」，且满足：烧伤病因分类 等于 电损伤未分型；或 烧伤病因分类 等于 雷击伤；或 烧伤病因分类 等于 混合后运行。',430,256,NULL,'ENABLED',8,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(698,2,698,'B14','吸入伤与燃烧产物中毒树','直接运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER, ISBI','直接运行。','直接运行。',72,584,NULL,'ENABLED',9,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(700,2,700,'B20','烧伤严重度与预后评分树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B11 烧伤面积与特殊部位树」，且满足：烧伤总面积 已取得有效值；完成「B12 化学烧伤风险树」；完成「B13 电损伤风险树」；完成「B14 吸入伤与燃烧产物中毒树」后运行。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B11 烧伤面积与特殊部位树」，且满足：烧伤总面积 已取得有效值；完成「B12 化学烧伤风险树」；完成「B13 电损伤风险树」；完成「B14 吸入伤与燃烧产物中毒树」后运行。',788,92,NULL,'ENABLED',11,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(702,2,702,'B22','环形焦痂与间隔综合征树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：ISBI, BURN-PRIMER','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B13 电损伤风险树」后运行。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B13 电损伤风险树」后运行。',788,256,NULL,'ENABLED',13,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(703,2,703,'B23','Ⅱ度烧伤水疱处理树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：CN-二型-2024-I','完成「B10 烧伤深度分级树」后运行。','完成「B10 烧伤深度分级树」后运行。',430,420,NULL,'ENABLED',14,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(704,2,704,'B24','烧伤创面感染树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：CN-二型-2024-二型, BURN-PRIMER','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值后运行。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值后运行。',430,584,NULL,'ENABLED',15,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(709,2,709,'B32','创面闭合与手术指征树','完成前置决策树后运行','依据创面上皮化比例、最终烧伤深度、感染等级、创基活力、供皮区状态和计划操作，判断创面闭合策略。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B24 烧伤创面感染树」，且满足：烧伤创面感染等级 已取得有效值后运行。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B24 烧伤创面感染树」，且满足：烧伤创面感染等级 已取得有效值后运行。',788,420,NULL,'ENABLED',20,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(712,2,712,'B41','烧伤康复与瘢痕风险树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：BURN-PRIMER, SCARS-PRIMER, CN-SCAR-2017','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B11 烧伤面积与特殊部位树」，且满足：烧伤总面积 已取得有效值；完成「B24 烧伤创面感染树」；完成「B32 创面闭合与手术指征树」，且满足：创面闭合策略 已取得有效值后运行。','完成「B10 烧伤深度分级树」，且满足：最终烧伤深度 已取得有效值；完成「B11 烧伤面积与特殊部位树」，且满足：烧伤总面积 已取得有效值；完成「B24 烧伤创面感染树」；完成「B32 创面闭合与手术指征树」，且满足：创面闭合策略 已取得有效值后运行。',1146,92,NULL,'ENABLED',23,'2026-07-29 17:22:58','2026-08-26 11:17:30'),(713,3,713,'S00','瘢痕来源树','直接运行','依据临床记录确定瘢痕来源，用于后续瘢痕评估。','直接运行。','直接运行。',72,92,NULL,'ENABLED',1,'2026-07-29 17:22:58','2026-08-25 23:07:30'),(716,3,716,'S11','瘢痕边界与形态树','直接运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：SCARS-PRIMER, CN-SCAR-2017, JSW-2018','直接运行。','直接运行。',72,256,NULL,'ENABLED',4,'2026-07-29 17:22:58','2026-08-25 23:21:22'),(717,3,717,'S12','瘢痕成熟与活动度树','直接运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：SCARS-PRIMER, CN-SCAR-2017','直接运行。','直接运行。',72,420,NULL,'ENABLED',5,'2026-07-29 17:22:58','2026-08-25 23:21:22'),(718,3,718,'S13','病理性瘢痕风险树','完成前置决策树后运行','依据医学指标初稿重建；已编译为可执行的指标节点/指标值节点图。来源：SCARS-PRIMER, CN-SCAR-2017, JSW-2018','完成「S00 瘢痕来源树」，且满足：瘢痕来源分类 已取得有效值后运行。','完成「S00 瘢痕来源树」，且满足：瘢痕来源分类 已取得有效值后运行