/*!40000 ALTER TABLE `llm_decision_tree` ENABLE KEYS */;

--
-- Table structure for table `llm_decision_node`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_decision_node` (
  `id` bigint NOT NULL COMMENT '决策节点ID',
  `tree_id` bigint NOT NULL COMMENT '所属决策树ID',
  `parent_id` bigint DEFAULT NULL COMMENT '旧版父节点ID，迁移期保留',
  `node_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '树内稳定节点键',
  `title` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点标题',
  `node_type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INDICATOR' COMMENT '节点类型',
  `indicator_code` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点对应指标编码',
  `indicator_stage` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标阶段',
  `value_code` varchar(180) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '指标值节点的规范值编码',
  `execution_mode` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MODEL_EDGE_SELECTION' COMMENT '节点执行模式',
  `input_indicator_codes` text COLLATE utf8mb4_unicode_ci COMMENT '允许读取的指标编码JSON',
  `condition_expression` text COLLATE utf8mb4_unicode_ci COMMENT '旧版条件表达式',
  `conclusion` text COLLATE utf8mb4_unicode_ci COMMENT '旧版节点结论',
  `detail` text COLLATE utf8mb4_unicode_ci COMMENT '旧版节点详情',
  `logic_description` longtext COLLATE utf8mb4_unicode_ci COMMENT '节点医学逻辑说明',
  `logic_definition_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '可执行结构化逻辑JSON',
  `logic_version` int NOT NULL DEFAULT '1' COMMENT '结构化逻辑版本',
  `action_payload_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '命中节点产生的动作JSON',
  `output_payload_json` longtext COLLATE utf8mb4_unicode_ci COMMENT '命中节点产生的指标输出JSON',
  `source_evidence` text COLLATE utf8mb4_unicode_ci COMMENT '节点医学来源证据',
  `clinical_lock_required` tinyint NOT NULL DEFAULT '0' COMMENT '是否需要临床确认：1是、0否',
  `position_x` int NOT NULL DEFAULT '80' COMMENT '画布横坐标',
  `position_y` int NOT NULL DEFAULT '80' COMMENT '画布纵坐标',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '节点排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_llm_node_tree_key` (`tree_id`,`node_key`),
  KEY `idx_llm_node_tree_sort` (`tree_id`,`sort_order`,`id`),
  KEY `idx_llm_node_parent` (`parent_id`),
  KEY `idx_llm_node_indicator` (`indicator_code`),
  CONSTRAINT `chk_llm_node_clinical_lock` CHECK ((`clinical_lock_required` in (0,1))),
  CONSTRAINT `chk_llm_node_logic_version` CHECK ((`logic_version` >= 1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI可执行决策图节点表';
