_13_indicator_value','瘢痕管理路径 = 辅助手术','INDICATOR_VALUE','scar_management_path','DECISION','辅助手术','FIXED_OUTPUT','[]',NULL,'瘢痕管理路径 = 辅助手术','瘢痕管理路径 = 辅助手术','瘢痕管理路径 = 辅助手术',NULL,1,'[{\"type\":\"CLINICAL_RECOMMENDATION\",\"text\":\"瘢痕管理路径 = 辅助手术\",\"requiresClinicianReview\":true,\"sourceTree\":\"S40\"}]','{\"indicatorCode\":\"scar_management_path\",\"value\":\"辅助手术\",\"status\":\"derived\",\"sourceTree\":\"S40\"}','SCARS-PRIMER, INT-SCAR, CN-SCAR-2017, JSW-2018',0,1010,3460,28,'2026-09-03 16:07:17','2026-09-03 16:07:17');
/*!40000 ALTER TABLE `llm_decision_node` ENABLE KEYS */;

--
-- Table structure for table `llm_decision_node_edge`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_decision_node_edge` (
  `id` bigint NOT NULL COMMENT '决策边ID',
  `tree_id` bigint NOT NULL COMMENT '所属决策树ID',
  `source_node_id` bigint NOT NULL COMMENT '起点节点ID',
  `target_node_id` bigint NOT NULL COMMENT '终点节点ID',
  `edge_key` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '树内稳定边键',
  `branch_label` varchar(240) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分支展示标签',
  `condition_expression` text COLLATE utf8mb4_unicode_ci COMMENT '旧版边条件表达式',
  `input_indicator_codes` text COLLATE utf8mb4_unicode_ci COMMENT '该边允许读取的指标编码JSON',
  `selector_mode` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MODEL_EDGE_SELECTION' COMMENT '选边模式',
  `priority_order` int NOT NULL DEFAULT '0' COMMENT '候选边优先级',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否为默认边：1是、0否',
  `clinical_lock_required` tinyint NOT NULL DEFAULT '0' COMMENT '是否需要临床确认：1是、0否',
  `source_evidence` text COLLATE utf8mb4_unicode_ci COMMENT '边的医学来源证据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_llm_node_edge_key` (`tree_id`,`edge_key`),
  KEY `idx_llm_edge_tree` (`tree_id`),
  KEY `idx_llm_edge_source_priority` (`source_node_id`,`priority_order`,`id`),
  KEY `idx_llm_edge_target` (`target_node_id`),
  CONSTRAINT `chk_llm_edge_clinical_lock` CHECK ((`clinical_lock_required` in (0,1))),
  CONSTRAINT `chk_llm_edge_default` CHECK ((`is_default` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI可执行决策图有向边表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
