--
-- Table structure for table `llm_decision_tree_dependency`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_decision_tree_dependency` (
  `id` bigint NOT NULL COMMENT '决策树依赖ID',
  `tree_id` bigint NOT NULL COMMENT '当前决策树ID',
  `prerequisite_tree_id` bigint NOT NULL COMMENT '必须先完成的决策树ID',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '前置树排序号',
  `condition_mode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧版单条件模式',
  `indicator_code` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧版单条件指标编码',
  `comparison_operator` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '旧版比较运算符',
  `expected_value` text COLLATE utf8mb4_unicode_ci COMMENT '旧版期望值',
  `condition_text` text COLLATE utf8mb4_unicode_ci COMMENT '旧版文本条件',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_llm_tree_dependency` (`tree_id`,`prerequisite_tree_id`),
  KEY `idx_llm_dependency_tree_sort` (`tree_id`,`sort_order`,`id`),
  KEY `idx_llm_dependency_prerequisite` (`prerequisite_tree_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI决策树前置依赖表';
/*!40101 SET character_set_client = @saved_cs_client */;

