/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `llm_decision_tree_dependency_condition` (
  `id` bigint NOT NULL COMMENT '依赖条件项ID',
  `dependency_id` bigint NOT NULL COMMENT '所属依赖关系ID',
  `card_group` int NOT NULL DEFAULT '0' COMMENT '条件卡片编号；卡内AND、卡间OR',
  `condition_mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '条件模式：INDICATOR或TEXT',
  `indicator_code` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参与比较的指标编码',
  `comparison_operator` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '比较运算符',
  `expected_value` text COLLATE utf8mb4_unicode_ci COMMENT '期望值',
  `condition_text` text COLLATE utf8mb4_unicode_ci COMMENT '文本条件',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '卡片内排序号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_llm_dependency_condition_card` (`dependency_id`,`card_group`,`sort_order`,`id`),
  KEY `idx_llm_dependency_condition_indicator` (`indicator_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI决策树前置依赖结构化条件表';
