  KEY `idx_llm_tree_indicator_sort` (`tree_id`,`sort_order`,`id`),
  KEY `idx_llm_tree_indicator_indicator` (`indicator_id`),
  CONSTRAINT `chk_llm_tree_indicator_required` CHECK ((`required` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI决策树与医学指标绑定表';
